rel = {"?": "mother", "!": "wife", "&": "brother", "x": "father"}
opts = {"A": "Z ? B x T & J ! L", "B": "Z ? B ! T & J x L", "C": "Z ! B x T ? J & L", "D": "Z & B ! T x J ? L"}

def means(expr):
    t = expr.split()
    facts = [(t[i], rel[t[i + 1]], t[i + 2]) for i in range(0, len(t) - 2, 2)]
    wife = [a for a, r, b in facts if r == "wife" and b == "L"]
    if not wife:
        return False
    w = wife[0]
    sibs = {w} | {a for a, r, b in facts if r == "brother" and b == w}
    fathers = [a for a, r, b in facts if r == "father" and b in sibs]
    if not fathers:
        return False
    mothers = [a for a, r, b in facts if r == "mother" and b == fathers[0]]
    return mothers == ["Z"]

