pattern = "_O_O__O_P_O_"
fills = {"A": "PPOOPOP", "B": "OOPPPOO", "C": "OPOPOOP", "D": "PPOOOPO"}
def fill(f):
    it = iter(f)
    return "".join(next(it) if c == "_" else c for c in pattern)
def periodic(s):
    return any(len(s) % n == 0 and s == s[:n] * (len(s) // n) for n in range(2, len(s) // 2 + 1))
opts = {k: periodic(fill(v)) for k, v in fills.items()}
result = True

match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

